def find_solutions(n, limit):
    solutions = []
    for a in range(1, limit):
        for b in range(a + 1, limit):
            # The equation is c^2(a+b) + c(a^2+b^2+3ab-4nab+1) + (a^2b+ab^2+a+b) = 0
            # Let's solve for c
            coeff_c2 = a + b
            coeff_c1 = a**2 + b**2 + 3*a*b - 4*n*a*b + 1
            coeff_c0 = a**2*b + a*b**2 + a + b

            import math
            discriminant = coeff_c1**2 - 4 * coeff_c2 * coeff_c0
            if discriminant >= 0:
                sqrt_d = math.isqrt(discriminant)
                if sqrt_d * sqrt_d == discriminant:
                    for sign in [-1, 1]:
                        num = -coeff_c1 + sign * sqrt_d
                        den = 2 * coeff_c2
                        if num % den == 0:
                            c = num // den
                            if c > 0 and c != a and c != b and a != b:
                                # To avoid duplicates, sort the triple
                                triple = tuple(sorted((a, b, c)))
                                if triple not in solutions:
                                    solutions.append(triple)
    return solutions

for n in [1, 2, 3, 4, 5, 6, 7]:
    sols = find_solutions(n, 50)
    print(f"n={n}, solutions={sols}")

